#!/usr/bin/env node
/**
 * Writes .next/build-meta.json so a locally-built, NSSM-run production
 * server can report which source state it was built from. CI platforms
 * (Vercel/GitHub Actions/Cloudflare Pages) already expose this via env vars
 * that lib/deploy/status.ts reads directly (VERCEL_GIT_COMMIT_SHA etc.) —
 * those take precedence when present. This file is the fallback for a
 * build that has no CI env, only a local git checkout. .next/ is
 * gitignored, so this is never source-controlled and is regenerated by
 * every build.
 *
 * Runs as `postbuild`, not `prebuild` — `next build` clears and regenerates
 * `.next/` itself, so anything written before it starts is wiped.
 */
import { execFileSync } from 'node:child_process'
import { mkdir, writeFile } from 'node:fs/promises'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const repoRoot = path.resolve(__dirname, '..')
const outDir = path.join(repoRoot, '.next')
const outFile = path.join(outDir, 'build-meta.json')

function git(args) {
  return execFileSync('git', args, { cwd: repoRoot, encoding: 'utf8' }).trim()
}

function resolveGitMeta() {
  try {
    const gitSha = git(['rev-parse', 'HEAD'])
    const gitShort = git(['rev-parse', '--short', 'HEAD'])
    const gitDirty = git(['status', '--porcelain']).length > 0
    let gitRef = null
    try {
      gitRef = git(['symbolic-ref', '-q', '--short', 'HEAD']) || null
    } catch {
      gitRef = null // detached HEAD — symbolic-ref exits non-zero, which is expected, not an error
    }
    return { gitSha, gitShort, gitDirty, gitRef }
  } catch (error) {
    console.warn('[write-build-meta] git unavailable or not a git checkout, writing unknown fields:', error.message)
    return { gitSha: null, gitShort: null, gitDirty: null, gitRef: null }
  }
}

async function main() {
  const meta = {
    ...resolveGitMeta(),
    builtAt: new Date().toISOString(),
  }
  await mkdir(outDir, { recursive: true })
  await writeFile(outFile, JSON.stringify(meta, null, 2) + '\n', 'utf8')
  console.log(`[write-build-meta] wrote ${path.relative(repoRoot, outFile)} (gitShort=${meta.gitShort ?? 'unknown'}, gitDirty=${meta.gitDirty ?? 'unknown'})`)
}

main().catch(error => {
  console.warn('[write-build-meta] failed, continuing build without metadata:', error)
})
